const siteCollectionBindingsAt = `-- name: SiteCollectionBindingsAt :many
SELECT DISTINCT ON (b.site_id) b.id,b.site_id,greatest(b.effective_from,m.attached_at)::timestamptz AS attributable_since FROM collection_bindings b
JOIN collection_plan_bindings m ON m.binding_id=b.id AND m.source_id=b.source_id
JOIN collection_plans p ON p.id=m.plan_id AND p.source_id=m.source_id
WHERE b.source_id=$1 AND b.site_id IS NOT NULL AND p.capability=$2 AND p.scope=$3
 AND m.attached_at<=$4::timestamptz
 AND (p.capability<>'web.dns' OR (p.params->'types') ? $5::text)
 AND b.effective_from<=$4::timestamptz
 AND (b.effective_until IS NULL OR b.effective_until>$4::timestamptz)
ORDER BY b.site_id,b.effective_from DESC,b.id DESC
`

type SiteCollectionBindingsAtParams struct {
	SourceID   uuid.UUID          `json:"source_id"`
	Capability string             `json:"capability"`
	Scope      []byte             `json:"scope"`
	EvidenceAt pgtype.Timestamptz `json:"evidence_at"`
	Rrtype     string             `json:"rrtype"`
}

type SiteCollectionBindingsAtRow struct {
	ID                uuid.UUID          `json:"id"`
	SiteID            *uuid.UUID         `json:"site_id"`
	AttributableSince pgtype.Timestamptz `json:"attributable_since"`
}

func (q *Queries) SiteCollectionBindingsAt(ctx context.Context, arg SiteCollectionBindingsAtParams) ([]SiteCollectionBindingsAtRow, error) {
	rows, err := q.db.Query(ctx, siteCollectionBindingsAt,
		arg.SourceID,
		arg.Capability,
		arg.Scope,
		arg.EvidenceAt,
		arg.Rrtype,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SiteCollectionBindingsAtRow{}
	for rows.Next() {
		var i SiteCollectionBindingsAtRow
		if err := rows.Scan(&i.ID, &i.SiteID, &i.AttributableSince); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

